class MovingAverage {
    private int size;
    private int[] data;
    private int count;
    private int s;

    /** Initialize your data structure here. */
    public MovingAverage(int size) {
        this.size = size;
        this.data = new int[size];
    }

    public double next(int val) {
        int idx = count % size;
        int oldVal = data[idx];
        data[idx] = val;
        s += (val - oldVal);
        ++count;
        return s * 1.0 / Math.min(size, count);
    }
}

